// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PickingTask) predicate.PickingTask {
	return predicate.PickingTask(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PickingTask) predicate.PickingTask {
	return predicate.PickingTask(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PickingTask) predicate.PickingTask {
	return predicate.PickingTask(sql.NotPredicates(p))
}
